export const shiftFaults={cableLow:'Tensión de cable insuficiente',cableHigh:'Tensión de cable excesiva',hTight:'Tope H demasiado cerrado',hOpen:'Tope H demasiado abierto',lTight:'Tope L demasiado cerrado',lOpen:'Tope L demasiado abierto',bClose:'Roldana demasiado cerca del cassette',bFar:'Roldana demasiado alejada del cassette',hanger:'Patilla desalineada',sticky:'Cable o funda con fricción excesiva',intermittentCable:'Atasco intermitente de guaya/funda'};
const setups={cableLow:[-.4,0,6],cableHigh:[.4,0,6],hTight:[0,.5,6],hOpen:[0,-.5,6],lTight:[0,0,5.5],lOpen:[0,0,6.5],bClose:[0,0,6],bFar:[0,0,6],hanger:[0,0,6],sticky:[0,0,6]};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export const combinedShiftCases=[['hanger','sticky'],['hanger','bFar'],['sticky','cableLow'],['bClose','lTight'],['hanger','sticky','bFar'],['hOpen','lOpen','cableHigh']];
export function createShift(mode='guided',random=Math.random){const ids=Object.keys(setups),pick=list=>list[Math.max(0,Math.min(list.length-1,Math.floor(random()*list.length)))],causes=mode==='guided'?['cableLow','hTight','lTight']:mode==='combined'?[...pick(combinedShiftCases)]:mode==='intermittent'?['intermittentCable']:[pick(ids)];const params={trim:0,h:0,l:6,b:1,hanger:false,sticky:false};for(const fault of causes){if(fault==='cableLow')params.trim=-.4;if(fault==='cableHigh')params.trim=.4;if(fault==='hTight')params.h=mode==='guided'?.4:.5;if(fault==='hOpen')params.h=-.5;if(fault==='lTight')params.l=mode==='guided'?5.6:5.5;if(fault==='lOpen')params.l=6.5;if(fault==='bClose')params.b=.4;if(fault==='bFar')params.b=1.7;if(fault==='hanger')params.hanger=true;if(fault==='sticky')params.sticky=true;}return {id:crypto.randomUUID(),mode,causes,...params,intermittent:mode==='intermittent',moves:0,trace:[],passes:{},revision:0,inspected:[],direction:1,initial:[params.trim,params.h,params.l,params.b],requested:3,test:'gear',checks:{},hints:0,errors:0,events:[],done:false,feedback:mode==='combined'?'Hay varias causas simultáneas. Aísla cada sistema y vuelve a medir tras cada intervención.':'Selecciona marchas y observa dónde se pierde la alineación. Inspecciona los extremos por separado.',hintUsed:false,hintKeys:[]};}
export function shiftHintTarget(s){return s.sticky||s.intermittent?'cable':s.hanger?'hanger':Math.abs(s.b-1)>.15?'b':Math.abs(s.h)>.14?'h':Math.abs(s.l-6)>.14?'l':Math.abs(s.trim)>.14?'trim':'verify';}
export function shiftHintAvailable(s){return !s.done&&(['combined','intermittent'].includes(s.mode)?!(s.hintKeys||[]).includes(shiftHintTarget(s)):!s.hintUsed);}
export function cableDragActive(s){return !!s.sticky||!!s.intermittent&&[false,true,true,false,false,true][s.moves%6];}
export function intermittentSweepComplete(s){return [1,2,3,4,5,6].every(g=>(s.passes?.['up'+g]||0)>=2)&&[0,1,2,3,4,5].every(g=>(s.passes?.['down'+g]||0)>=2);}
export function shiftState(s){const drag=cableDragActive(s);const raw=s.test==='h'?-1:s.test==='l'?7:s.requested+s.trim+(s.hanger?(s.requested-3)*.18:0)+(drag?-s.direction*.35:0),position=clamp(raw,s.h,s.l),target=s.test==='h'?0:s.test==='l'?6:s.requested,error=position-target,unsafe=position<-.15||position>6.15||s.b<.55,aligned=Math.abs(error)<.15&&!unsafe&&Math.abs(s.b-1)<.16;return {position,target,error,unsafe,aligned,gap:s.b,hangerAngle:s.hanger?.16:0,cableDrag:drag,engaged:clamp(Math.round(position),0,6),teeth:[12,14,16,19,23,28,32][clamp(Math.round(position),0,6)],status:Math.abs(s.b-1)>=.16?(s.b<1?'Separación insuficiente: riesgo de contacto roldana/cassette':'Separación excesiva: guiado menos preciso'):unsafe?'Fuera del rango seguro: riesgo de salida de cadena':aligned?'Guía alineada con la corona objetivo':error<0?'Guía desplazada hacia las coronas pequeñas':'Guía desplazada hacia las coronas grandes'};}
export const shiftScore=s=>Math.max(0,100-10*s.hints-5*s.errors);
export function shiftAct(s,action,key,value){if(s.done)return false;
 if(action==='select'&&Number.isInteger(value)&&value>=0&&value<=6){const moved=value!==s.requested,adjacent=Math.abs(value-s.requested)===1;if(moved){s.direction=Math.sign(value-s.requested);s.moves++;}s.requested=value;s.test='gear';const v=shiftState(s);s.checks['g'+value]=v.aligned;if(moved&&s.mode==='intermittent'){const key=(s.direction>0?'up':'down')+value;if(v.aligned&&adjacent)s.passes[key]=(s.passes[key]||0)+1;else s.passes[key]=0;s.trace.push({move:s.moves,gear:value+1,direction:s.direction,position:v.position,error:v.error,drag:v.cableDrag,aligned:v.aligned,revision:s.revision});s.trace=s.trace.slice(-120);}s.feedback=v.status;return true;}
 if(action==='test'&&['h','l'].includes(key)){s.test=key;const v=shiftState(s);s.checks[key]=v.aligned;s.feedback=(key==='h'?'Prueba H: se aísla la tensión del cable para examinar el extremo pequeño. ':'Prueba L: se examina el extremo grande. ')+v.status;return true;}
 if(action==='inspect'&&['b','hanger','cable'].includes(key)){if(!s.inspected.includes(key))s.inspected.push(key);s.checks[key]=key==='b'?Math.abs(s.b-1)<.16:key==='hanger'?!s.hanger:!cableDragActive(s);s.feedback=key==='b'?'Separación relativa roldana/cassette: '+s.b.toFixed(1)+'; objetivo didáctico 1,0 (no milímetros).':key==='hanger'?(s.hanger?'El útil de alineación muestra desviación que cambia a lo largo del cassette.':'El útil de alineación no muestra desviación en este modelo.'):(cableDragActive(s)?'La prueba de deslizamiento muestra resistencia y retorno incompleto. Compara la misma marcha llegando desde ambos lados.':'La guaya desliza libremente en este instante. Una lectura normal no descarta intermitencia: repite subidas y bajadas.');return true;}
 if(action==='repair'&&['hanger','cable'].includes(key)){if(!s.inspected.includes(key)){s.feedback='Inspecciona antes de intervenir.';return false;}if(key==='cable'&&s.intermittent&&!s.trace.some(t=>t.drag&&t.revision===s.revision)){s.feedback='Registra primero un episodio de retorno anormal al subir o bajar marchas; una inspección normal aislada no basta.';return false;}const field=key==='hanger'?'hanger':'sticky',good=s[field]||(key==='cable'&&s.intermittent);if(good){s[field]=false;if(key==='cable')s.intermittent=false;}else s.errors++;s.checks={};s.passes={};s.revision++;s.events.push({repair:key,good,remaining:s.causes.filter(f=>f==='hanger'?s.hanger:f==='sticky'?s.sticky:f==='intermittentCable'?s.intermittent:f.startsWith('b')?Math.abs(s.b-1)>.15:f.startsWith('h')?Math.abs(s.h)>.14:f.startsWith('l')?Math.abs(s.l-6)>.14:Math.abs(s.trim)>.14)});s.feedback=good?(key==='hanger'?'Patilla sustituida por una compatible y alineación verificada en el modelo. Repite todas las pruebas.':'Cable y funda defectuosos sustituidos; recorrido y deslizamiento comprobados. Repite todas las pruebas.'):'Intervención innecesaria: no había ese defecto. −5 puntos.';return true;}
 if(action==='adjust'&&['trim','h','l','b'].includes(key)&&[-1,1].includes(value)){const old=Math.abs(s.trim)+Math.abs(s.h)+Math.abs(s.l-6)+Math.abs(s.b-1),ranges={trim:[-.8,.8],h:[-.8,.8],l:[5.2,6.8],b:[.3,1.8]},next=Number(clamp(s[key]+value*.1,...ranges[key]).toFixed(2));if(next===s[key])return false;s[key]=next;const worse=Math.abs(s.trim)+Math.abs(s.h)+Math.abs(s.l-6)+Math.abs(s.b-1)>old+.001;if(worse)s.errors++;s.checks={};s.passes={};s.revision++;s.events.push({key,delta:value*.1,worse});s.feedback=(s.mode==='guided'?(worse?'Este ajuste se aleja del objetivo. −5 puntos. ':'Ajuste en la dirección correcta. '):'Ajuste registrado. ')+ 'Vuelve a comprobar extremos y siete marchas; las pruebas anteriores se invalidan tras un ajuste.';return true;}
 if(action==='hint'){if(!shiftHintAvailable(s))return false;s.hintUsed=true;s.hints++;s.hintKeys??=[];s.hintKeys.push(shiftHintTarget(s));s.feedback=shiftHintTarget(s)==='verify'?'Las causas activas están corregidas. Repite las comprobaciones finales después de la última intervención.':s.intermittent?'Recorre 1→7→1 varias veces. Compara en el registro la misma marcha y sentido: unas maniobras fallan y otras no. Captura un episodio antes de sustituir guaya/funda.':s.sticky?'Si una marcha queda distinta al llegar desde arriba o desde abajo, prueba el deslizamiento del cable antes de compensar con tensión.':s.hanger?'Si puedes alinear el centro pero no ambos extremos, mide la patilla con el útil. El tensor no endereza una patilla.':Math.abs(s.b-1)>.15?'Inspecciona la separación entre roldana guía y cassette. Ajusta B al objetivo del modelo; en la bici real consulta medida y condición de suspensión indicadas.':Math.abs(s.h)>.14?'Aísla el cable y alinea el tope H con la corona pequeña. No uses el tensor para compensar un tope.':Math.abs(s.l-6)>.14?'Comprueba el extremo grande con la prueba L: debe alcanzarlo sin permitir salida hacia los radios.':'Si ambos extremos están bien pero fallan varias marchas intermedias, ajusta el tensor en pequeños pasos y recorre todo el cassette.';return true;}
 if(action==='verify'){const complete=['h','l','b','hanger','cable',...Array.from({length:7},(_,i)=>'g'+i)].every(k=>s.checks[k]===true),calibrated=Math.abs(s.trim)<.15&&Math.abs(s.h)<.15&&Math.abs(s.l-6)<.15&&Math.abs(s.b-1)<.16&&!s.hanger&&!s.sticky&&!s.intermittent;s.done=complete&&calibrated&&(s.mode!=='intermittent'||intermittentSweepComplete(s));if(!s.done)s.errors++;s.feedback=s.done?'Transmisión verificada: siete marchas, topes, separación B, patilla y cable correctos. En la bicicleta real confirma también alineación de patilla, longitud de cadena, ajuste B, fijaciones y prueba segura según el fabricante.':'Verificación incompleta o ajuste incorrecto. En modo intermitente se requieren dos pasadas completas de subida y bajada tras la última intervención. Repite las pruebas H, L, B, patilla, cable y las siete marchas después del último ajuste. −5 puntos.';return true;}return false;
}
